def rellenar_fecha_registro(apps, schema_editor):
    Sacramento = apps.get_model('sacramentos', 'Sacramento')
    Sacramento.objects.filter(fecha_registro__isnull=True).update(
        fecha_registro=models.F('fecha')
    )


def copiar_anotaciones(apps, schema_editor):
    Bautismo = apps.get_model('sacramentos', 'Bautismo')
    for bautismo in Bautismo.objects.all().iterator():
        partes = [
            texto
            for texto in (bautismo.anotaciones, bautismo.anotacion)
            if texto and texto.strip()
        ]
        if not partes:
            continue
        sacramento = bautismo.sacramento
        sacramento.observaciones = "\n".join(partes)
        sacramento.save(update_fields=['observaciones'])


